// Sprungnavigation der Startseite (UX-Audit P2-7): kompakte Chips direkt unter dem Hero.
// Mobil klebt die Leiste beim Scrollen unter dem Seitenkopf (68 px), ab md steht sie normal im Fluss.
// Server-Komponente, reine Anker-Links – funktioniert ohne JavaScript.

const ZIELE = [
  { id: "loesungen", label: "Lösungen" },
  { id: "boerse", label: "Börse" },
  { id: "energie", label: "Energie" },
  { id: "tools", label: "Tools" },
  { id: "faq", label: "FAQ" },
];

export default function Sprungnavigation() {
  return (
    <nav
      aria-label="Auf dieser Seite"
      className="sticky top-[68px] z-30 border-b border-ink-200/70 bg-white/90 backdrop-blur-xl backdrop-saturate-150 md:static md:bg-white md:backdrop-blur-none"
    >
      <ul className="ov-container flex gap-2 overflow-x-auto py-2.5 [scrollbar-width:none] md:justify-center md:py-3">
        {ZIELE.map((z) => (
          <li key={z.id} className="shrink-0">
            <a
              href={`#${z.id}`}
              className="flex min-h-10 items-center rounded-full bg-sand-50 px-4 text-[14px] font-semibold text-ink-800 ring-1 ring-ink-200/70 transition-colors hover:bg-ov-50 hover:text-ov-800 hover:ring-ov-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ov-500"
            >
              {z.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}
import { PHASEN } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

/**
 * Werttreppe eines Freiflächenprojekts: Kaufpreisspanne je kWp nach
 * Entwicklungsphase (ohne Bestand – der liegt eine Größenordnung höher und
 * würde die Skala sprengen; er steht als Fußnote darunter).
 * Reine Server-Komponente, Balken in CSS, Werte aus markt.js.
 */
export default function Werttreppe() {
  const stufen = PHASEN.filter((p) => p.id !== "cod");
  const bestand = PHASEN.find((p) => p.id === "cod");
  const max = Math.max(...stufen.map((p) => p.preisProKwp.max));
  return (
    <figure className="rounded-[2rem] bg-white p-6 shadow-xl ring-1 ring-ink-200/70 md:p-8">
      <figcaption className="flex flex-wrap items-baseline justify-between gap-2">
        <span className="font-display text-[19px] font-bold text-ink-900">Projektwert nach Phase</span>
        <span className="text-[12.5px] text-ink-500">Kaufpreis je kWp, Spanne DACH</span>
      </figcaption>
      <ol className="mt-7 space-y-4">
        {stufen.map((p, i) => {
          const links = (p.preisProKwp.min / max) * 100;
          const breite = ((p.preisProKwp.max - p.preisProKwp.min) / max) * 100;
          return (
            <li key={p.id} className="grid grid-cols-[minmax(0,9.5rem)_1fr] items-center gap-4 sm:grid-cols-[minmax(0,12rem)_1fr]">
              <div className="min-w-0">
                <p className="truncate text-[14px] font-semibold text-ink-900">{p.kurz}</p>
                <p className="text-[12px] text-ink-500">Risiko {p.risiko}</p>
              </div>
              <div className="relative h-9 rounded-full bg-ink-100">
                <div
                  className="absolute inset-y-1 flex items-center justify-end rounded-full bg-gradient-to-r from-ov-400 to-ov-600 px-3"
                  style={{ left: `${links}%`, width: `${Math.max(breite, 18)}%`, opacity: 0.55 + (i / stufen.length) * 0.45 }}
                >
                  <span className="ov-num whitespace-nowrap text-[12px] font-bold text-white">
                    {fmt(p.preisProKwp.min)}–{fmt(p.preisProKwp.max)} €
                  </span>
                </div>
              </div>
            </li>
          );
        })}
      </ol>
      <p className="mt-6 border-t border-ink-100 pt-4 text-[12.5px] leading-relaxed text-ink-500">
        Bestandsanlagen (in Betrieb) werden nach Ertragswert gehandelt, typischerweise {fmt(bestand.preisProKwp.min)}–{fmt(bestand.preisProKwp.max)} € je kWp.
        Orientierungswerte – Netzanschluss, Tarif und Standort verschieben die Spanne deutlich.
      </p>
    </figure>
  );
}
import { ArrowRight } from "lucide-react";
import Link from "next/link";
import Reveal from "@/components/ui/Reveal";
import ProjektKarte from "@/components/Boerse/ProjektKarte";
import { backend } from "@/lib/plattform/backend";

/**
 * Die neuesten Projekte der Börse auf der Startseite – nur öffentliche
 * Teaser-Felder (liefert die Börse ohnehin nur so aus). Ist die Plattform
 * nicht erreichbar oder leer, rendert der Abschnitt gar nichts.
 */
export default async function HomeBoerse({ anzahl = 3 }) {
  let projekte = [];
  try {
    const daten = await backend().boerse(null, {});
    projekte = (daten?.projekte || []).slice(0, anzahl);
  } catch {
    return null;
  }
  if (projekte.length === 0) return null;

  return (
    <div className="mt-16 border-t border-ink-100 pt-12">
      <div className="mb-8 flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-[12.5px] font-semibold uppercase tracking-[0.16em] text-ov-700">Aktuell in der Börse</p>
          <p className="mt-2 font-display text-[clamp(1.35rem,1.1rem+0.8vw,1.75rem)] font-extrabold tracking-tight text-ink-900">Neue Projekte – anonymisiert bis zur NDA</p>
        </div>
        <Link href="/projektboerse" className="group inline-flex items-center gap-1.5 text-[15px] font-semibold text-ov-700 hover:text-ov-800">
          Alle Projekte <ArrowRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover:translate-x-1" />
        </Link>
      </div>
      <ul className="grid gap-5 md:grid-cols-3">
        {projekte.map((p, i) => (
          <Reveal as="li" key={p.slug} delay={i * 80}>
            <ProjektKarte projekt={p} href={`/projektboerse/${p.slug}`} />
          </Reveal>
        ))}
      </ul>
    </div>
  );
}
/**
 * Tiefen-Ebenen für dunkle Heros (Startseite, Landingpages).
 *
 * Rein dekorativ (aria-hidden), Server-Komponente, keine Hex-Werte:
 * Farben kommen über currentColor bzw. Token-Variablen.
 *
 *  1. Lichtkegel oben rechts (Sonne, sehr dezent) und grünes Bodenlicht
 *  2. Fluchtlinien wie Modulreihen, die zum Horizont laufen
 *  3. Energiefluss-Linien, die einmal einlaufen (ov-linie, stroke-dashoffset)
 *  4. wenige schwebende Lichtpunkte (animate-ov-float, nur transform)
 *
 * Unter prefers-reduced-motion steht alles still im Endzustand.
 * Elternelement braucht `relative isolate overflow-hidden`.
 */
const PUNKTE = [
  { x: 62, y: 22, r: 2.2, d: "-1.2s", o: 0.7 },
  { x: 78, y: 38, r: 1.6, d: "-3.4s", o: 0.55 },
  { x: 88, y: 18, r: 1.4, d: "-5.1s", o: 0.45 },
  { x: 70, y: 58, r: 2, d: "-2.3s", o: 0.5 },
  { x: 94, y: 48, r: 1.2, d: "-4.2s", o: 0.4 },
  { x: 54, y: 70, r: 1.4, d: "-6s", o: 0.35 },
];

export default function HeroTiefe({ className = "" }) {
  return (
    <div aria-hidden="true" className={`pointer-events-none absolute inset-0 -z-10 ${className}`}>
      {/* 1 – Licht */}
      <div
        className="absolute -right-[10%] -top-[30%] h-[80%] w-[60%] rounded-full opacity-70"
        style={{ background: "radial-gradient(closest-side, color-mix(in oklab, var(--color-sun-300) 22%, transparent), transparent)" }}
      />
      <div
        className="absolute -bottom-[35%] left-[10%] h-[70%] w-[70%] rounded-full"
        style={{ background: "radial-gradient(closest-side, color-mix(in oklab, var(--color-ov-500) 26%, transparent), transparent)" }}
      />

      {/* 2 + 3 – Linien (nur ab Tablet, mobil bleibt die Fläche ruhig) */}
      <svg
        viewBox="0 0 100 60"
        preserveAspectRatio="xMidYMid slice"
        className="ov-sofort absolute inset-0 hidden h-full w-full md:block"
      >
        <g className="text-white" stroke="currentColor" strokeWidth="0.08" fill="none" opacity="0.14">
          {Array.from({ length: 9 }, (_, i) => (
            <line key={i} x1={58 + i * 5.5} y1="60" x2={80 + i * 0.6} y2="30" />
          ))}
          {[38, 44, 52].map((y) => (
            <line key={y} x1="50" y1={y} x2="100" y2={y - 2} />
          ))}
        </g>
        <g className="text-ov-300" stroke="currentColor" fill="none" strokeLinecap="round">
          <path d="M 46 58 C 60 50, 66 40, 82 34 S 98 26, 104 22" strokeWidth="0.18" opacity="0.55" pathLength="1" className="ov-linie" style={{ "--ov-delay": "500ms" }} />
          <path d="M 58 62 C 70 52, 76 46, 90 42 S 100 38, 106 36" strokeWidth="0.12" opacity="0.35" pathLength="1" className="ov-linie" style={{ "--ov-delay": "750ms" }} />
        </g>
      </svg>

      {/* 4 – Lichtpunkte */}
      <div className="absolute inset-0 hidden md:block">
        {PUNKTE.map((p, i) => (
          <span
            key={i}
            className="absolute rounded-full bg-ov-300 motion-safe:animate-ov-float"
            style={{
              left: `${p.x}%`,
              top: `${p.y}%`,
              width: `${p.r * 3}px`,
              height: `${p.r * 3}px`,
              opacity: p.o,
              animationDelay: p.d,
              boxShadow: "0 0 12px 2px color-mix(in oklab, var(--color-ov-300) 55%, transparent)",
            }}
          />
        ))}
      </div>
    </div>
  );
}
